/** Değişken içeren kalıplar: [desen, çeviri] */
export const EN_DESEN: [RegExp, (m: RegExpExecArray, t: (s: string) => string) => string][] = [
  [/^Sulanmayan (.+) için temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `Basic nitrogen requirement for unirrigated ${t(b(m[1])).toLowerCase()}: ${m[2]} kg/da.`; }], /* tahil */
  [/^(\d+) su verilen (.+) daha yüksek verim verir; temel azot ihtiyacı ([\d.,]+) kg\/da\.$/, (m, t) => { const b = (x: string) => x.charAt(0).toLocaleUpperCase('tr-TR') + x.slice(1); return `${((x) => x.charAt(0).toLocaleUpperCase() + x.slice(1))(t(b(m[2])))} given ${m[1]} irrigations yields more; basic nitrogen requirement ${m[3]} kg/da.`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak kendiliğinden az azot verir, azot hedefi ([\d.,]+) kg\/da artırıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Organic matter ${m[1]} % (${({"çok az": "very low", "az": "low", "orta": "medium", "iyi": "good", "yüksek": "high", "çok yüksek": "very high", "yeterli": "sufficient"} as Record<string, string>)[m[2]] ?? m[2]}): the soil releases little nitrogen by itself, so the nitrogen target was raised by ${m[3]} kg/da (total ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \((.+?)\): toprak azotun bir kısmını kendisi verir, azot hedefi ([\d.,]+) kg\/da azaltıldı \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Organic matter ${m[1]} % (${({"çok az": "very low", "az": "low", "orta": "medium", "iyi": "good", "yüksek": "high", "çok yüksek": "very high", "yeterli": "sufficient"} as Record<string, string>)[m[2]] ?? m[2]}): the soil supplies part of the nitrogen itself, so the nitrogen target was lowered by ${m[3]} kg/da (total ${m[4]} kg/da).`; }], /* tahil */
  [/^Organik madde %([\d.,]+) \(orta\): azot hedefi değiştirilmedi \(toplam ([\d.,]+) kg\/da\)\.$/, (m) => { return `Organic matter ${m[1]} % (medium): nitrogen target unchanged (total ${m[2]} kg/da).`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): ekimde ([\d.,]+) kg\/da saf fosfor \(P₂O₅\) verilir\.$/, (m) => { return `Phosphorus ${m[1]} kg/da (${({"çok az": "very low", "az": "low", "orta": "medium", "iyi": "good", "yüksek": "high", "çok yüksek": "very high", "yeterli": "sufficient"} as Record<string, string>)[m[2]] ?? m[2]}): ${m[3]} kg/da pure phosphorus (P₂O₅) is given at sowing.`; }], /* tahil */
  [/^Fosfor ([\d.,]+) kg\/da \((.+?)\): fosforlu gübreye gerek yok\.$/, (m) => { return `Phosphorus ${m[1]} kg/da (${({"çok az": "very low", "az": "low", "orta": "medium", "iyi": "good", "yüksek": "high", "çok yüksek": "very high", "yeterli": "sufficient"} as Record<string, string>)[m[2]] ?? m[2]}): no phosphate fertiliser needed.`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): ([\d.,]+) kg\/da saf potasyum \(K₂O\) eklendi\.$/, (m) => { return `Potassium ${m[1]} kg/da (${({"çok az": "very low", "az": "low", "orta": "medium", "iyi": "good", "yüksek": "high", "çok yüksek": "very high", "yeterli": "sufficient"} as Record<string, string>)[m[2]] ?? m[2]}): ${m[3]} kg/da pure potassium (K₂O) added.`; }], /* tahil */
  [/^Potasyum ([\d.,]+) kg\/da \((.+?)\): potasyumlu gübreye gerek yok\.$/, (m) => { return `Potassium ${m[1]} kg/da (${({"çok az": "very low", "az": "low", "orta": "medium", "iyi": "good", "yüksek": "high", "çok yüksek": "very high", "yeterli": "sufficient"} as Record<string, string>)[m[2]] ?? m[2]}): no potash fertiliser needed.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(düşük\): taban gübresi çinkolu seçildi, yapraktan çinko önemli\.$/, (m) => { return `Zinc ${m[1]} mg/kg (low): a zinc-containing base fertiliser was chosen; foliar zinc is important.`; }], /* tahil */
  [/^Çinko ([\d.,]+) mg\/kg \(yeterli\)\.$/, (m) => { return `Zinc ${m[1]} mg/kg (sufficient).`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(düşük\): kanola bora çok ihtiyaç duyar; tomurcuk ve çiçeklenmedeki yapraktan bor \(MICROSENSE Ca & B\) uygulamalarını atlamayın\.$/, (m) => { return `Boron ${m[1]} mg/kg (low): oilseed rape needs a lot of boron; do not skip the foliar boron (MICROSENSE Ca & B) at bud and flowering.`; }], /* tahil */
  [/^Bor ([\d.,]+) mg\/kg \(yeterli\); yapraktan bor yine de çiçek tutumunu destekler\.$/, (m) => { return `Boron ${m[1]} mg/kg (sufficient); foliar boron still supports pod set.`; }], /* tahil */
  [/^Kanola kükürde çok ihtiyaç duyar \(yaklaşık 4 kg\/da\); plandaki gübreler ≈ ([\d.,]+) kg\/da veriyor, kapsül döneminde yapraktan potasyum ve kükürt uygulamasını atlamayın\.$/, (m) => { return `Oilseed rape needs a lot of sulphur (about 4 kg/da); the fertilisers in the plan supply ≈ ${m[1]} kg/da, so do not skip the foliar potassium and sulphur at pod stage.`; }], /* tahil */
  [/^Bezelye baklagildir; azotun çoğunu kökündeki bakterilerden alır\. Yalnızca ([\d.,]+) kg\/da başlangıç azotu verilir\.$/, (m) => { return `Peas are legumes and get most of their nitrogen from the bacteria in their roots. Only ${m[1]} kg/da of starter nitrogen is given.`; }], /* tahil */
  [/^Kireç %([\d.,]+): çinko ve fosfor alımı zorlaşır; fosfor çinkolu taban gübresiyle, azotun bir kısmı kükürtlü gübreyle \(ör\. amonyum sülfat\) verilir\.$/, (m) => `Lime ${m[1]} %: zinc and phosphorus uptake is hindered; the phosphorus is given with a zinc-containing base fertiliser and part of the nitrogen as a sulphur fertiliser (e.g. ammonium sulphate).`],
  [/^en az (.+)$/, (m) => `minimum ${m[1]}`],
  [/^en çok (.+)$/, (m) => `maximum ${m[1]}`],
  [/^Bünye: (.+)$/, (m) => `Texture: ${m[1]}`],
  [/^(\d+) saat$/, (m) => `${m[1]} h`],
  [/^(.+) için bu değer olağan dışı görünüyor\.$/, (m) => `This value looks unusual for ${m[1]}.`],
  [/^Kum \+ silt \+ kil toplamı %(.+) çıktı; %100 olmalı\. Değerleri kontrol edin\.$/, (m) => `Sand + silt + clay add up to ${m[1]} %; they should add up to 100 %. Check the values.`],
  [/^(.+) bitkisinde (.+) noksanlığı$/, (m, t) => `${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))} deficiency in ${t(m[1]).toLowerCase()}`],
  [/^(.+) bitkisinde (.+)$/, (m, t) => `${t(m[2].charAt(0).toLocaleUpperCase('tr-TR') + m[2].slice(1))} in ${t(m[1]).toLowerCase()}`],
  [/^(.+) bitkisinde$/, (m, t) => `in ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1)).toLowerCase()}`],
  [/^Azotlu gübre miktarını biraz azaltın; her 1\.000 m³ su ≈ (.+) kg azot getirir\.$/, (m) => `Reduce nitrogen fertiliser slightly; every 1000 m³ of water brings ≈ ${m[1]} kg of nitrogen.`],
  [/^([A-Z][A-Za-z]{0,2}\d*) \((.+) Bünyeli\)$/, (m) => `${m[1]} (${m[2]})`],
  [/^([\d.,]+)( puan| [^\s(]+)? (eksik|fazla) \(%([\d.,]+)\)$/, (m) => `${m[1]}${m[2] === ' puan' ? ' points' : m[2] ?? ''} ${m[3] === 'eksik' ? 'below' : 'above'} (${m[4]} %)`],
  [/^(.+) noksanlığı$/, (m, t) => `${t(m[1])} deficiency`],
  [/^(.+) bu tuzluluktan etkilenmez\.$/, (m, t) => `${t(m[1])}: not affected by this salinity.`],
  [/^Bu tuzlulukta (.+) için beklenen verim yaklaşık %(\d+) \(tuzsuz suya göre\)\.$/, (m, t) => `At this salinity, the expected yield of ${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1)).toLowerCase()} is about ${m[2]} % (compared with salt-free water).`],
  [/^(.+) tuza (.+)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} to salt.`],
  [/^(.+) bora (.+) \(sınır (.+)–(.+) mg\/l\)\.$/, (m, t) => `${t(m[1])}: ${t(m[2])} to boron (limit ${m[3]}–${m[4]} mg/l).`],
  [/^Toprağa ya da suya jips verin: .*\(sizde ≈ (.+) kg \/ 1\.000 m³\)\.$/, (m) => `Add gypsum to the soil or the water: for every 1 me/l of RSC, about 86 kg of pure gypsum per 1000 m³ of water (in your case ≈ ${m[1]} kg / 1000 m³).`],
  [/^Bitkinin ihtiyacından yaklaşık %(\d+) fazla su verin \(yıkama suyu\); tuz kök bölgesinden uzaklaşır\.$/, (m) => `Give about ${m[1]} % more water than the crop needs (leaching water); this moves the salt away from the root zone.`],
  [/^Bu su için (.+) sulama daha uygun; imkânınız varsa geçmeyi düşünün\.$/, (m, t) => `${t(m[1].charAt(0).toLocaleUpperCase('tr-TR') + m[1].slice(1))} irrigation is more suitable for this water; if you can, consider switching.`],
  [/^Sodyum ya da klorür yüksek \((.+) me\/l\): yaprak yanığı yapabilir; yalnızca akşam ve gece sulayın\.$/, (m) => `High sodium or chloride (${m[1]} me/l): it can scorch the leaves; irrigate only in the evening and at night.`],
];
